-- Permission vocabulary and system roles of the budget module
-- Generated by metaphor-schema
--
-- Writes into the identity module's tables (public.permissions, public.roles,
-- public.role_permissions), so those migrations must have run first. Inserts what is
-- missing and never deletes or revokes: what a tenant changed survives a re-run.

DO $$
BEGIN
    IF to_regclass('public.permissions') IS NULL
       OR to_regclass('public.roles') IS NULL
       OR to_regclass('public.role_permissions') IS NULL THEN
        RAISE NOTICE 'seed of the budget permissions skipped: the identity module has not created public.permissions, public.roles and public.role_permissions';
        RETURN;
    END IF;

    UPDATE public.permissions p SET description = v.description
      FROM (VALUES
            ('budget:create'::text, 'budget'::text, 'create'::text, 'Create budget'::text),
            ('budget:delete'::text, 'budget'::text, 'delete'::text, 'Delete budget'::text),
            ('budget:purge'::text, 'budget'::text, 'purge'::text, 'Purge budget'::text),
            ('budget:read'::text, 'budget'::text, 'read'::text, 'Read budget'::text),
            ('budget:restore'::text, 'budget'::text, 'restore'::text, 'Restore budget'::text),
            ('budget:update'::text, 'budget'::text, 'update'::text, 'Update budget'::text),
            ('budget_line:create'::text, 'budget_line'::text, 'create'::text, 'Create budget line'::text),
            ('budget_line:delete'::text, 'budget_line'::text, 'delete'::text, 'Delete budget line'::text),
            ('budget_line:purge'::text, 'budget_line'::text, 'purge'::text, 'Purge budget line'::text),
            ('budget_line:read'::text, 'budget_line'::text, 'read'::text, 'Read budget line'::text),
            ('budget_line:restore'::text, 'budget_line'::text, 'restore'::text, 'Restore budget line'::text),
            ('budget_line:update'::text, 'budget_line'::text, 'update'::text, 'Update budget line'::text)
      ) AS v(name, resource, action, description)
     WHERE p.name = v.name AND (p.metadata->>'deleted_at') IS NULL
       AND p.description IS DISTINCT FROM v.description;

    INSERT INTO public.permissions (name, resource, action, description)
    SELECT v.name, v.resource, v.action, v.description
      FROM (VALUES
            ('budget:create'::text, 'budget'::text, 'create'::text, 'Create budget'::text),
            ('budget:delete'::text, 'budget'::text, 'delete'::text, 'Delete budget'::text),
            ('budget:purge'::text, 'budget'::text, 'purge'::text, 'Purge budget'::text),
            ('budget:read'::text, 'budget'::text, 'read'::text, 'Read budget'::text),
            ('budget:restore'::text, 'budget'::text, 'restore'::text, 'Restore budget'::text),
            ('budget:update'::text, 'budget'::text, 'update'::text, 'Update budget'::text),
            ('budget_line:create'::text, 'budget_line'::text, 'create'::text, 'Create budget line'::text),
            ('budget_line:delete'::text, 'budget_line'::text, 'delete'::text, 'Delete budget line'::text),
            ('budget_line:purge'::text, 'budget_line'::text, 'purge'::text, 'Purge budget line'::text),
            ('budget_line:read'::text, 'budget_line'::text, 'read'::text, 'Read budget line'::text),
            ('budget_line:restore'::text, 'budget_line'::text, 'restore'::text, 'Restore budget line'::text),
            ('budget_line:update'::text, 'budget_line'::text, 'update'::text, 'Update budget line'::text)
      ) AS v(name, resource, action, description)
     WHERE NOT EXISTS (SELECT 1 FROM public.permissions p WHERE p.name = v.name AND (p.metadata->>'deleted_at') IS NULL)
    ON CONFLICT DO NOTHING;

END $$;
